/**
 * Renders the UI kit table into the SDK's TypeScript types
 * (`src/plugin-sdk/ui.generated.ts`). `pnpm generate:plugin-ui` writes the file;
 * a gate test fails when it is stale.
 *
 * Like the Plugin API codegen, the output is plain declarations: prop types,
 * event handler types, and the tag union. The runtime components and the host
 * map are built from the same table, so a new row is a new declaration.
 */

import {
  PLUGIN_UI_TABLE,
  type PluginUiElement,
  type PluginUiEventDetail,
  type PluginUiProp,
} from "@/plugin-sdk/ui-table";

const GENERATED_NOTE =
  "Generated by `pnpm generate:plugin-ui` from src/plugin-sdk/ui-table.ts. Do not edit.";

function propType(prop: PluginUiProp): string {
  switch (prop.kind) {
    case "string":
      return "string";
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "enum":
      return (prop.values ?? []).map((value) => JSON.stringify(value)).join(" | ") || "never";
    case "options":
      return "readonly PluginUiOption[]";
    case "keys":
      return "readonly string[]";
    case "node":
      return "ReactNode";
  }
}

function eventDetailType(detail: PluginUiEventDetail): string {
  switch (detail) {
    case "string":
      return "string";
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "keys":
      return "readonly string[]";
    case "none":
      return "void";
  }
}

function doc(text: string): string {
  return `/** ${text.replace(/\*\//g, "*\\/")} */`;
}

function renderElementProps(element: PluginUiElement): string {
  const lines: string[] = [];
  for (const [name, prop] of Object.entries(element.props)) {
    // Internal props are set by the SDK, never by a Plugin, so they are not part
    // of the public per-element props.
    if (prop.internal === true) continue;
    const optional = prop.required ? "" : "?";
    if (prop.description !== undefined) lines.push(`    ${doc(prop.description)}`);
    lines.push(`    ${name}${optional}: ${propType(prop)};`);
  }
  for (const event of element.events) {
    const handler =
      event.detail === "none"
        ? "() => void"
        : `(event: { detail: ${eventDetailType(event.detail)} }) => void`;
    if (event.description !== undefined) lines.push(`    ${doc(event.description)}`);
    lines.push(`    ${event.prop}?: ${handler};`);
  }
  const summary = element.interactive
    ? `${element.summary} Keyboard-interactive.`
    : element.summary;
  return `  ${doc(summary)}\n  ${JSON.stringify(element.tag)}: {\n${lines.join("\n")}\n  };`;
}

/** The SDK's `ui.generated.ts`: tags, option type, and per-element props. */
export function renderPluginUiTypes(table: readonly PluginUiElement[] = PLUGIN_UI_TABLE): string {
  const tags = table.map((element) => `  ${JSON.stringify(element.tag)},`).join("\n");
  const props = table.map(renderElementProps).join("\n");
  const components = table
    .map(
      (element) =>
        `  ${element.component}: ComponentType<PluginUiElementProps[${JSON.stringify(element.tag)}]>;`
    )
    .join("\n");
  return `// ${GENERATED_NOTE}

import type { ComponentType, ReactNode } from "react";

export const PLUGIN_UI_TAGS = [
${tags}
] as const;

export type PluginUiTag = (typeof PLUGIN_UI_TAGS)[number];

export interface PluginUiOption {
  value: string;
  label: string;
}

/** The props and events of every element in the UI kit, by tag. */
export interface PluginUiElementProps {
${props}
}

/** The SDK component name to component type, generated from the table. */
export interface PluginUiComponents {
${components}
}
`;
}
